 void startTiles()throws Exception{
  setInTouchMode(false);
  ui(()->{
   store.prefs.edit().putString("ten_group_@nota","Productivity").putString("ten_group_@files","Productivity").putString("ten_group_@browser","Explore").apply();
   TenStartData data=new TenStartData(store);check(data.rename("Productivity","My work"),"Rename group");check(data.add("Reading"),"New group");
   store.prefs.edit().putBoolean("ten_full_start",true).apply();home.refreshTen();StartMenu start=TenSmoke.find(root,StartMenu.class);start.hide();start.show(false);
  });
  await(()->{View tile=TenSmoke.description(TenSmoke.find(root,StartMenu.class),"Nth Nota, Medium Start tile");return tile!=null&&tile.isShown()&&tile.getWidth()>0;},"Start tiles laid out");
  AtomicInteger old=new AtomicInteger();
  ui(()->{
   StartMenu start=TenSmoke.find(root,StartMenu.class);check(TenSmoke.description(start,"Rename tile group My work")!=null,"Renamed group shown");
   View tile=TenSmoke.description(start,"Nth Nota, Medium Start tile");old.set(store.startPins().indexOf("@nota"));int next=store.startPins().indexOf("@files");
   check(tile.requestFocusFromTouch(),"Keyboard tile focus: "+focusState(tile));tile.dispatchKeyEvent(new KeyEvent(0,0,KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_DPAD_RIGHT,0,KeyEvent.META_CTRL_ON));
   check(store.startPins().indexOf("@nota")==next,"Keyboard tile reorder stays in its group");
  });
  await(()->{View moved=TenSmoke.description(TenSmoke.find(root,StartMenu.class),"Nth Nota, Medium Start tile");return moved!=null&&moved.hasFocus();},"Keyboard focus survives reorder");
  ui(()->{
   StartMenu start=TenSmoke.find(root,StartMenu.class);View moved=TenSmoke.description(start,"Nth Nota, Medium Start tile");moved.performAccessibilityAction(0x01020051,Bundle.EMPTY);
   check(store.startPins().indexOf("@nota")==old.get(),"Accessible tile reorder");
   try{DesktopBackup.Plan plan=DesktopBackup.parse(DesktopBackup.snapshot(store).toString());check(TenStartData.parse(plan.string(TenStartData.KEY,"[]")).contains("My work"),"Group backup roundtrip");TenDesktops.validate(new JSONObject(plan.string(TenDesktops.KEY,"{}")));}catch(JSONException e){throw new RuntimeException(e);}
  });
  waitForIdleSync();ui(()->{StartMenu start=TenSmoke.find(root,StartMenu.class);FrameLayout host=(FrameLayout)start.getParent();check(start.getWidth()>=host.getWidth()-Aero.dp(home,16),"Full-screen Start uses workspace width");});shot("ten-polish-start-landscape");
  ui(()->home.setRequestedOrientation(ActivityInfo.SCREEN_ORIENTATION_PORTRAIT));await(()->root.getHeight()>root.getWidth(),"Portrait");
  ui(()->{StartMenu start=TenSmoke.find(root,StartMenu.class);start.hide();start.show(false);});shot("ten-polish-start-portrait");
 }
 void notifications()throws Exception{ui(()->{TenSmoke.find(root,StartMenu.class).hide();home.open("ten-setting:notification-access");check(TenSmoke.text(TenSmoke.find(root,TenSettings.class),"Choose notification access")!=null,"Optional notification access control");});String component=getTargetContext().getPackageName()+"/com.nthexperience.desktop.TenNotifications";shell("cmd notification allow_listener "+component);await(()->TenNotifications.allowed(getTargetContext()),"Notification access granted in isolated emulator");shell("cmd notification post -t Ten-integration-fixture ten-polish Local-test-notification");await(()->TenNotifications.rows(getTargetContext()).stream().anyMatch(r->r.title.contains("Ten-integration-fixture")),"Real notification listener feed");ui(()->home.open("@tenactions"));shot("ten-polish-notifications");ui(()->{store.prefs.edit().putBoolean("ten_focus",true).apply();check(TenNotifications.rows(home).isEmpty(),"Focus assist filters feed");store.prefs.edit().putBoolean("ten_focus",false).apply();});shell("cmd notification disallow_listener "+component);await(()->!TenNotifications.allowed(getTargetContext())&&TenNotifications.rows(getTargetContext()).isEmpty(),"Revocation clears feed");}
