 void assistantAvailability()throws Exception{getTargetContext().getSharedPreferences("ten-nota-ai-privacy",0).edit().putBoolean("cloud-allowed",false).putInt("consent-version",1).commit();BlockingQueue<JSONObject> results=new LinkedBlockingQueue<>();TenAssistant assistant=new TenAssistant(getTargetContext(),results::add);try{assistant.request("native_fixture","polish","The desktop are ready.");long end=SystemClock.uptimeMillis()+40000;JSONObject terminal=null;while(SystemClock.uptimeMillis()<end){JSONObject event=results.poll(1,TimeUnit.SECONDS);if(event!=null&&event.optString("event").equals("result")){terminal=event;break;}}check(terminal!=null,"On-device availability returns a terminal result");check(terminal.has("error")||terminal.optBoolean("local"),"Local result or transparent unavailable state");check(!new JSONObject(assistant.cloud.state()).optBoolean("allowed"),"Cloud opt-in remains off");}finally{assistant.close();}}
 byte[] read(Uri uri)throws Exception{try(InputStream in=getTargetContext().getContentResolver().openInputStream(uri);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[1024];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return out.toByteArray();}}
