 String focusState(View tile){StringBuilder s=new StringBuilder();for(View v=tile;v!=null;v=v.getParent() instanceof View?(View)v.getParent():null)s.append(v.getClass().getSimpleName()).append("[touch=").append(v.isInTouchMode()).append(",focusable=").append(v.isFocusable()).append(",enabled=").append(v.isEnabled()).append(",visible=").append(v.getVisibility()).append(",size=").append(v.getWidth()).append("x").append(v.getHeight()).append(v instanceof ViewGroup?",desc="+((ViewGroup)v).getDescendantFocusability():"").append("] ");return s.toString();}
 interface Condition {boolean get();}void check(boolean v,String why){if(!v)throw new AssertionError(why);}void ui(Runnable run)throws Exception{FutureTask<Void> task=new FutureTask<>(run,null);home.runOnUiThread(task);task.get(15,TimeUnit.SECONDS);}void await(Condition condition,String message)throws Exception{long end=SystemClock.uptimeMillis()+15000;while(SystemClock.uptimeMillis()<end){FutureTask<Boolean> task=new FutureTask<>(condition::get);home.runOnUiThread(task);if(task.get(10,TimeUnit.SECONDS))return;Thread.sleep(80);}throw new AssertionError(message);}
