 void systemClick(String label)throws Exception{long end=SystemClock.uptimeMillis()+10000;while(SystemClock.uptimeMillis()<end){AccessibilityNodeInfo node=findNode(getUiAutomation().getRootInActiveWindow(),label);if(node!=null){android.graphics.Rect r=new android.graphics.Rect();node.getBoundsInScreen(r);long now=SystemClock.uptimeMillis();MotionEvent down=MotionEvent.obtain(now,now,MotionEvent.ACTION_DOWN,r.centerX(),r.centerY(),0),up=MotionEvent.obtain(now,now+60,MotionEvent.ACTION_UP,r.centerX(),r.centerY(),0);sendPointerSync(down);sendPointerSync(up);down.recycle();up.recycle();waitForIdleSync();return;}Thread.sleep(80);}throw new AssertionError("Missing system row "+label);}
 AccessibilityNodeInfo findNode(AccessibilityNodeInfo node,String text){if(node==null)return null;if(text.contentEquals(node.getText()==null?"":node.getText())||text.contentEquals(node.getContentDescription()==null?"":node.getContentDescription()))return node;for(int i=0;i<node.getChildCount();i++){AccessibilityNodeInfo match=findNode(node.getChild(i),text);if(match!=null)return match;}return null;}
